    redacted = data.copy()
    messages = redacted.get("messages", [])
    for msg in messages:
        if msg.get("role") == "system":
            if isinstance(msg.get("content"), str):
                msg["content"] = "<REDACTED>"
            elif isinstance(msg.get("content"), list):
                msg["content"] = [{"type": "text", "text": "<REDACTED>"}]
    return redacted

